export const brandLogoPath = '/images/branding/mpho-madi-logo-horizontal.png'
/**
 * Resized copies of brandLogoPath, generated by scripts/build-logo-derivatives.mjs
 * (plain resamples; the original file is untouched and stays the 1672w
 * candidate). The header shows the logo at most ~128 CSS px wide and the
 * arrival animation at most 520px, so most screens never need the 1672px
 * original.
 */
export const brandLogoSrcSet = [
  '/images/branding/mpho-madi-logo-horizontal-327w.png 327w',
  '/images/branding/mpho-madi-logo-horizontal-629w.png 629w',
  '/images/branding/mpho-madi-logo-horizontal-1107w.png 1107w',
  '/images/branding/mpho-madi-logo-horizontal.png 1672w',
].join(', ')
/** Header logo: h-11 (44px tall, ~79px wide); md:h-16 is 4rem = 72px tall, ~128px wide (the root font size is 18px from md up). Keep in step with SiteHeader and index.html. */
export const brandLogoHeaderSizes = '(min-width: 768px) 128px, 79px'
// Reversed (all-white) mark for dark grounds — the navy footer. Using it
// there means the logo no longer needs a white plate behind it.
export const brandLogoWhitePath = '/images/branding/mpho-madi-logo-horizontal-white.png'
export const brandLogoAlt = 'Mpho Madi Trust Fund logo'

export const siteNav = previewNavigation

// No payment provider is confirmed for the Trust yet, so there is no external
// donation URL to link to. Every visitor-facing "donate" affordance routes to
// the enquiry form on the Donate page instead. Do not reintroduce a placeholder
// URL here: a donate button that leads somewhere fake is worse than one that
// leads to a real conversation. When a provider IS confirmed, export the real
// URL and point the Donate CTAs at it.
export const donateEnquiryPath = '/donate#enquiry-form'

export const trackCta = (eventName) => {
  if (typeof window !== 'undefined') {
    window.dataLayer = window.dataLayer || []
    window.dataLayer.push({ event: eventName })
  }
}
